// ── myDATA Excel template helpers (single-line multi-apartment splits) ──────
// ΕΠΙΜΕΡΙΣΜΟΣ parser: ''/ΙΣΟΜΕΡΩΣ → equal · ΠΛΗΡΕΣ → full amount to each ·
// custom percentages '60/40' or '50/30/20' (order = COST CENTER → 2 → 3).
function xlParseAlloc(str,n){
  const s=String(str||'').trim();
  if(!s)return{mode:'equal'};
  const u=s.toUpperCase();
  if(u==='ΙΣΟΜΕΡΩΣ'||u==='EQUAL')return{mode:'equal'};
  if(u==='ΠΛΗΡΕΣ'||u==='FULL')return{mode:'full'};
  if(/^\d+([.,]\d+)?(\/\d+([.,]\d+)?)+$/.test(s)){
    const pct=s.split('/').map(x=>parseFloat(x.replace(',','.')));
    const sum=pct.reduce((a,b)=>a+b,0);
    if(pct.length===n&&sum>99.5&&sum<100.5)return{mode:'pct',pct};
  }
  return{mode:'equal',fallback:true};
}
function xlIsCredit(t){return /^5(\.|$)/.test(String(t||'').trim());} // myDATA 5.1/5.2 credit notes
const xlR2=v=>Math.round(v*100)/100;
function xlAllocAmt(total,shares){ // round shares to 2dp; cent remainder → first portion (sums stay exact)
  const out=shares.map(sh=>xlR2(total*sh));
  out[0]=xlR2(total-out.slice(1).reduce((a,b)=>a+b,0));
  return out;
}
// One template row → 1..3 expense portions. Amounts never change in the sheet;
// the allocation is computed here so the sheet's ΕΛΕΓΧΟΙ totals always reconcile with myDATA.
function xlSplitPortions(net,vat,total,ccs,allocStr){
  if(ccs.length<=1)return[{cc:ccs[0]||'',net,vat,total}];
  const a=xlParseAlloc(allocStr,ccs.length);
  if(a.mode==='full')return ccs.map(cc=>({cc,net,vat,total}));
  const shares=a.mode==='pct'?a.pct.map(p=>p/100):ccs.map(()=>1/ccs.length);
  const nets=xlAllocAmt(net,shares),vats=xlAllocAmt(vat,shares),tots=xlAllocAmt(total,shares);
  return ccs.map((cc,i)=>({cc,net:nets[i],vat:vats[i],total:tots[i]}));
}

