  let _loading = false, _dirty = false;

  function _esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;'); }
  function _by() { return (window._ACC && window._ACC.user) || localStorage.getItem('elysian_user_name') || 'Team'; }
  function _todayISO() { return new Date().toISOString().slice(0, 10); }
  function _dm(iso) { if (!iso) return ''; const p = String(iso).split('-'); return p.length === 3 ? parseInt(p[2]) + '/' + parseInt(p[1]) : iso; }

  function _compressImage(file, cb) {
    const reader = new FileReader();
    reader.onload = function (e) {
      const img = new Image();
      img.onload = function () {
        const MAX = 1280; let w = img.width, h = img.height;
        if (w > MAX || h > MAX) { const s = MAX / Math.max(w, h); w = Math.round(w * s); h = Math.round(h * s); }
        const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
        cv.getContext('2d').drawImage(img, 0, 0, w, h);
        cb(cv.toDataURL('image/jpeg', 0.72));
      };
      img.onerror = function () { cb(null); };
      img.src = e.target.result;
    };
    reader.onerror = function () { cb(null); };
    reader.readAsDataURL(file);
  }

  function _complianceStatus(due) {
    if (!due) return { level: 'none', label: 'no date' };
    const d = new Date(due + 'T00:00:00'); if (isNaN(d)) return { level: 'none', label: 'no date' };
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const days = Math.round((d - today) / 86400000);
    if (days < 0) return { level: 'red', label: 'overdue ' + (-days) + 'd', days: days };
    if (days <= COMPLIANCE_SOON_DAYS) return { level: 'amber', label: 'in ' + days + 'd', days: days };
    return { level: 'green', label: 'valid · ' + days + 'd', days: days };
  }
  // exposed for the dashboard card + tests
  window._pinfoStatus = _complianceStatus;
  window._pinfoItems = COMPLIANCE_ITEMS;

  function _seedHouseRules(apt) {
    const hr = {};
    HOUSE_RULE_FIELDS.forEach(function (f) { const k = f[0]; if (apt && apt[k] != null && apt[k] !== '') hr[k] = apt[k]; });
    return hr;
  }

  async function _load(rentalId) {
    _loading = true; renderPropInfo();
    try {
      const r = await fetch('/api/rental-info/' + encodeURIComponent(rentalId));
      const data = r.ok ? await r.json() : {};
      _cur = {
        amenities: data.amenities || {},
        faqs: Array.isArray(data.faqs) ? data.faqs : [],
        houseRules: data.houseRules || {},
        compliance: data.compliance || {},
      };
      const apt = (S.apts || []).find(function (a) { return a.id === rentalId; }) || {};
      const seed = _seedHouseRules(apt);
      Object.keys(seed).forEach(function (k) { if (_cur.houseRules[k] == null || _cur.houseRules[k] === '') _cur.houseRules[k] = seed[k]; });
      if (_cur.houseRules.min_stay_on == null) _cur.houseRules.min_stay_on = !!(_cur.houseRules.minimum_length_of_stay);
    } catch (e) {
      _cur = { amenities: {}, faqs: [], houseRules: {}, compliance: {} };
    }
    _loading = false; _dirty = false; renderPropInfo();
  }

  async function _save(silent) {
    if (!_selRentalId) return;
    let payload;
    try { payload = JSON.stringify(_cur); } catch (e) { if (typeof toast === 'function') toast('Save failed: data could not be serialized.', 'err'); return; }
    try {
      const r = await fetch('/api/rental-info/' + encodeURIComponent(_selRentalId), {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: payload,
      });
      if (r.ok) {
        _dirty = false;
        if (_all) _all[_selRentalId] = JSON.parse(payload);
        if (!silent && typeof toast === 'function') toast('Saved.', 'ok');
        renderPropInfo();
        if (window._cmplRefresh) window._cmplRefresh();
        return;
      }
      let reason = 'HTTP ' + r.status;
      try { const j = await r.json(); if (j && j.error) reason = j.error; } catch (e2) {}
      if (r.status === 404) reason = 'endpoint not found — deploy server.js v11';
      else if (r.status === 503) reason = 'no database connected on the server';
      if (typeof toast === 'function') toast('Save failed: ' + reason, 'err');
    } catch (e) {
      if (typeof toast === 'function') toast('Save failed: network error.', 'err');
    }
  }

  // ── handlers ──
  window.pinfoSelectRental = function (id) { _selRentalId = id || null; _view = 'edit'; if (id) _load(id); else renderPropInfo(); };
  window.pinfoSearch = function (v) {
    _q = String(v || '').toLowerCase();
    const sel = document.getElementById('pinfo-sel'); if (sel) sel.innerHTML = _pickerOptions();
  };
  window.pinfoView = function (v) { _view = v; renderPropInfo(); if (v === 'matrix' && !_all) _loadAll(); };
  window.pinfoToggle = function (aid) {
    const a = _cur.amenities[aid] || { on: false, note: '' };
    a.on = !a.on; _cur.amenities[aid] = a; _dirty = true;
    const row = document.getElementById('amrow-' + aid);
    if (row) row.outerHTML = _amenityRowHtml(aid, _amLabel(aid));
    _markDirty();
  };
  window.pinfoNote = function (aid, val) {
    const a = _cur.amenities[aid] || { on: true, note: '' };
    a.note = val; _cur.amenities[aid] = a; _dirty = true; _markDirty();
  };
  window.pinfoRule = function (k, val) { _cur.houseRules[k] = val; _dirty = true; _markDirty(); };
  window.pinfoMinStayToggle = function () {
    _cur.houseRules.min_stay_on = !_cur.houseRules.min_stay_on;
    if (!_cur.houseRules.min_stay_on) _cur.houseRules.minimum_length_of_stay = '';
    _dirty = true; renderPropInfo();
  };
  window.pinfoAmaNumber = function (val) {
    _cur.compliance.ama = _cur.compliance.ama || {};
    _cur.compliance.ama.number = val; _dirty = true; _markDirty();
  };
  window.pinfoAmaCopy = function (btn) {
    const n = (_cur.compliance.ama || {}).number || '';
    const done = function () { if (btn) { const o = btn.textContent; btn.textContent = '✓'; setTimeout(function () { btn.textContent = o; }, 900); } };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(n).then(done).catch(function () {});
  };
  window.pinfoIssued = function (itemId, val) {
    const rec = _cur.compliance[itemId] = _cur.compliance[itemId] || {};
    rec.issuedOn = val;
    if (val && CADENCE[itemId] && (!rec.due || rec.dueAuto)) {
      const d = new Date(val + 'T00:00:00'); d.setMonth(d.getMonth() + CADENCE[itemId]);
      rec.due = d.toISOString().slice(0, 10); rec.dueAuto = true;
    }
    _dirty = true; renderPropInfo();
  };
  window.pinfoCompDate = function (itemId, val) {
    const rec = _cur.compliance[itemId] = _cur.compliance[itemId] || {};
    rec.due = val; rec.dueAuto = false; _dirty = true; renderPropInfo();
  };
  window.pinfoAddFaq = function () { _cur.faqs.push({ q: '', a: '' }); _dirty = true; renderPropInfo(); };
  window.pinfoFaq = function (i, field, val) { if (_cur.faqs[i]) { _cur.faqs[i][field] = val; _dirty = true; _markDirty(); } };
  window.pinfoDelFaq = function (i) { _cur.faqs.splice(i, 1); _dirty = true; renderPropInfo(); };
  window.pinfoCopy = function (aid, btn) {
    const text = _amSentence(aid);
    const done = function () { if (btn) { const o = btn.textContent; btn.textContent = '✓'; setTimeout(function () { btn.textContent = o; }, 1000); } };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done).catch(function () { fallbackCopy(text, done); });
    else fallbackCopy(text, done);
  };
  function fallbackCopy(text, cb) {
    try {
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select(); document.execCommand('copy');
      document.body.removeChild(ta); if (cb) cb();
    } catch (e) { if (typeof toast === 'function') toast('Copy failed.', 'err'); }
  }
  window.pinfoSave = function () { _save(false); };

  // ── Law 5170 files (proof_files, month='law5170') ──
  window.pinfoFileAdd = function (itemId, input) {
    const files = input && input.files ? Array.prototype.slice.call(input.files) : [];
    if (!files.length || !_selRentalId) return;
    const apt = (S.apts || []).find(function (a) { return a.id === _selRentalId; }) || {};
    const it = COMPLIANCE_ITEMS.find(function (x) { return x.id === itemId; }) || { label: itemId };
    let pending = files.length, added = 0;
    files.forEach(function (f) {
      if (f.size > 15 * 1024 * 1024) { if (typeof toast === 'function') toast(_esc(f.name) + ' is over 15 MB — not uploaded.', 'err'); if (--pending === 0) finish(); return; }
      const isImg = /^image\//.test(f.type);
      const push = function (dataUrl, mime, name) {
        if (!dataUrl) { if (--pending === 0) finish(); return; }
        const b64 = dataUrl.split(',')[1] || '';
        fetch('/api/proofs', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            month: 'law5170', task: itemId, aptId: _selRentalId, aptName: apt.name || '',
            name: name, mime: mime, size: Math.round(b64.length * 0.75), by: _by(), dataB64: b64,
          }),
        }).then(function (r) { return r.ok ? r.json() : null; }).then(function (j) {
          if (j && j.id != null) {
            const rec = _cur.compliance[itemId] = _cur.compliance[itemId] || {};
            rec.files = rec.files || [];
            rec.files.push({ id: j.id, name: name, by: _by(), at: _todayISO(), mime: mime });
            added++;
          }
          if (--pending === 0) finish();
        }).catch(function () { if (--pending === 0) finish(); });
      };
      const normName = (apt.name || 'Apartment') + ' — ' + it.label + ' — ' + _todayISO() + ' — ' + f.name;
      if (isImg) _compressImage(f, function (dataUrl) { push(dataUrl, 'image/jpeg', normName.replace(/\.[^.]+$/, '') + '.jpg'); });
      else {
        const r2 = new FileReader();
        r2.onload = function (e) { push(e.target.result, f.type || 'application/pdf', normName); };
        r2.onerror = function () { push(null); };
        r2.readAsDataURL(f);
      }
    });
    function finish() {
      if (added) { _dirty = true; _save(true); if (typeof toast === 'function') toast(added + ' file' + (added > 1 ? 's' : '') + ' saved.', 'ok'); }
      renderPropInfo();
    }
  };
  window.pinfoFileDel = function (itemId, fid) {
    if (!confirm('Delete this file? This cannot be undone.')) return;
    fetch('/api/proofs/' + fid, { method: 'DELETE' }).catch(function () {});
    const rec = _cur.compliance[itemId] || {};
    rec.files = (rec.files || []).filter(function (f) { return String(f.id) !== String(fid); });
    _dirty = true; _save(true); renderPropInfo();
  };
  window.pinfoFileOpen = function (fid, dl) { window.open('/api/proofs/' + fid + (dl ? '?dl=1' : ''), '_blank'); };

  // ── Inspection pack: everything for one apartment as a ZIP (client-side, JSZip) ──
  function _jszip() {
    return new Promise(function (res, rej) {
      if (window.JSZip) return res(window.JSZip);
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
      s.onload = function () { res(window.JSZip); };
      s.onerror = function () { rej(new Error('JSZip load failed')); };
      document.head.appendChild(s);
    });
  }
  window.pinfoZip = async function (btn) {
    if (!_selRentalId) return;
    const apt = (S.apts || []).find(function (a) { return a.id === _selRentalId; }) || {};
    const old = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'Packing…'; }
    try {
      const JSZip = await _jszip();
      const zip = new JSZip();
      let n = 0;
      for (const it of COMPLIANCE_ITEMS) {
        const rec = _cur.compliance[it.id] || {};
        for (const f of (rec.files || [])) {
          try {
            const r = await fetch('/api/proofs/' + f.id);
            if (!r.ok) continue;
            zip.file(it.label.replace(/[\/\\]/g, '-') + '/' + String(f.name || ('file-' + f.id)).replace(/[\/\\]/g, '-'), await r.blob());
            n++;
          } catch (e) {}
        }
      }
      if (!n) { if (typeof toast === 'function') toast('No files to pack for this apartment yet.', 'err'); }
      else {
        const ama = ((_cur.compliance.ama || {}).number || '').trim();
        const blob = await zip.generateAsync({ type: 'blob' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = (ama ? 'AMA-' + ama + ' — ' : '') + (apt.name || 'Apartment') + ' — Law5170.zip';
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(function () { URL.revokeObjectURL(a.href); }, 4000);
        if (typeof toast === 'function') toast('Inspection pack: ' + n + ' files.', 'ok');
        if (typeof logChange === 'function') logChange('files', 'inspection-pack', (apt.name || _selRentalId) + ' · ' + n + ' files');
      }
    } catch (e) { if (typeof toast === 'function') toast('ZIP failed: ' + e.message, 'err'); }
    if (btn) { btn.disabled = false; btn.textContent = old; }
  };

  function _markDirty() {
    const b = document.getElementById('pinfo-save');
    if (b) { b.disabled = false; b.textContent = '💾 Save changes'; b.style.opacity = '1'; }
    const d = document.getElementById('pinfo-dirty'); if (d) d.style.display = '';
  }
  function _amItem(aid) {
    for (const g of AMENITY_GROUPS) { for (const it of g[1]) if (it.id === aid) return it; }
    return null;
  }
  function _amLabel(aid) { const it = _amItem(aid); return it ? it.label : aid; }
  function _amSentence(aid) {
    const it = _amItem(aid);
    const a = _cur.amenities[aid] || { note: '' };
    if (!it) return (a.note || '').trim();
    const fill = (a.note || '').trim();
    if (it.type === 'check') return it.label;
    if (it.type === 'select') return fill ? ((it.selPrefix || it.label) + ' ' + fill).trim() : it.label;
    if (it.type === 'prefix') return fill ? (it.prefix + ' ' + fill) : it.label;
    return fill ? (it.label + ': ' + fill) : it.label;
  }

  // ── rendering ──
  const IN = 'font-size:12px;padding:4px 8px;border:1px solid var(--bdr);border-radius:6px;background:var(--bg);color:var(--tx)';
  function _pill(st) {
    const c = st.level === 'red' ? ['var(--bg-err)', 'var(--bdr-err)', 'var(--tx-err)']
      : st.level === 'amber' ? ['var(--bg-warn)', 'var(--bdr-warn)', 'var(--tx-warn)']
      : st.level === 'green' ? ['var(--bg-ok)', 'var(--bdr-ok)', 'var(--tx-ok)']
      : ['var(--bg2)', 'var(--bdr)', 'var(--tx3)'];
    return '<span style="font-size:10px;font-weight:600;padding:2px 8px;border-radius:9px;background:' + c[0] + ';border:1px solid ' + c[1] + ';color:' + c[2] + ';white-space:nowrap">' + st.label + '</span>';
  }
  function _fileChips(itemId) {
    const rec = _cur.compliance[itemId] || {};
    const chips = (rec.files || []).map(function (f) {
      const nm = String(f.name || ('file ' + f.id));
      const short = nm.length > 26 ? nm.slice(0, 24) + '…' : nm;
      return '<span style="display:inline-flex;align-items:center;gap:5px;border:1px solid var(--bdr);border-radius:14px;padding:2px 8px;font-size:11px;background:var(--bg2);max-width:100%">' +
        '<span onclick="pinfoFileOpen(\'' + f.id + '\')" title="' + _esc(nm) + (f.by ? ' · ' + _esc(f.by) : '') + (f.at ? ' · ' + _esc(f.at) : '') + ' — click to preview" style="cursor:pointer;color:var(--tx2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">📎 ' + _esc(short) + '</span>' +
        '<span onclick="pinfoFileOpen(\'' + f.id + '\',1)" title="Download" style="cursor:pointer;color:var(--tx3)">⬇</span>' +
        '<span onclick="pinfoFileDel(\'' + itemId + '\',\'' + f.id + '\')" title="Delete file" style="cursor:pointer;color:var(--tx-err);font-weight:700">×</span>' +
        '</span>';
    }).join(' ');
    const add = '<label style="display:inline-flex;align-items:center;gap:4px;border:1px dashed var(--bdr2);border-radius:14px;padding:2px 9px;font-size:11px;color:var(--tx3);cursor:pointer">＋ file' +
      '<input type="file" multiple accept="image/*,application/pdf" onchange="pinfoFileAdd(\'' + itemId + '\',this)" style="display:none"></label>';
    return '<div style="display:flex;flex-wrap:wrap;gap:5px;align-items:center">' + chips + add + '</div>';
  }
  function _complianceBoardHtml() {
    const rows = COMPLIANCE_ITEMS.map(function (it) {
      const rec = _cur.compliance[it.id] || {};
      if (it.type === 'ama') {
        return '<div style="display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid var(--bdr);flex-wrap:wrap">' +
          '<div style="flex:1;min-width:210px"><div style="font-size:13px;font-weight:600;color:var(--tx)">' + _esc(it.label) + '</div>' +
          '<div style="margin-top:3px;display:flex;gap:6px;align-items:center"><input type="text" value="' + _esc(rec.number) + '" oninput="pinfoAmaNumber(this.value)" placeholder="fill in the ΑΜΑ number…" style="' + IN + ';width:190px">' +
          '<button onclick="pinfoAmaCopy(this)" title="Copy ΑΜΑ" class="btn sm" style="font-size:11px;padding:3px 8px">⧉</button></div></div>' +
          '<div style="flex:2;min-width:240px">' + _fileChips(it.id) + '</div>' +
          '<div style="width:230px"></div></div>';
      }
      const st = _complianceStatus(rec.due);
      return '<div style="display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid var(--bdr);flex-wrap:wrap">' +
        '<div style="flex:1;min-width:210px"><div style="font-size:13px;font-weight:600;color:var(--tx)">' + _esc(it.label) +
        (it.optional ? ' <span style="font-size:10px;color:var(--tx3);font-weight:400">(optional)</span>' : '') + '</div>' +
        '<div style="margin-top:3px">' + _pill(st) + '</div></div>' +
        '<div style="flex:2;min-width:240px">' + _fileChips(it.id) + '</div>' +
        '<div style="display:flex;gap:10px">' +
        '<div style="display:flex;flex-direction:column;gap:2px"><span style="font-size:9px;color:var(--tx3)">issued on</span>' +
        '<input type="date" value="' + _esc(rec.issuedOn) + '" onchange="pinfoIssued(\'' + it.id + '\',this.value)" style="' + IN + '"></div>' +
        '<div style="display:flex;flex-direction:column;gap:2px"><span style="font-size:9px;color:var(--tx3)">due date' + (rec.dueAuto ? ' <span style="color:#C9A84C">· auto</span>' : '') + '</span>' +
        '<input type="date" value="' + _esc(rec.due) + '" onchange="pinfoCompDate(\'' + it.id + '\',this.value)" style="' + IN + '"></div>' +
        '</div></div>';
    }).join('');
    const cnt = function (lvl) { return COMPLIANCE_ITEMS.filter(function (it) { return _complianceStatus((_cur.compliance[it.id] || {}).due).level === lvl; }).length; };
    const overdue = cnt('red'), soon = cnt('amber');
    return '<div style="margin-top:26px;border-top:2px solid var(--bdr);padding-top:16px">' +
      '<div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;flex-wrap:wrap">' +
      '<div style="font-size:15px;font-weight:700;color:var(--tx)">⚖️ Compliance (Law 5170/2025)</div>' +
      (overdue ? '<span style="font-size:11px;color:var(--tx-err);font-weight:600">' + overdue + ' overdue</span>' : '') +
      (soon ? '<span style="font-size:11px;color:var(--tx-warn);font-weight:600">' + soon + ' due soon</span>' : '') +
      '<span style="flex:1"></span>' +
