// ── Email report to owner ─────────────────────────────────────────────────────
// Renders the exact Export-PDF document into a real multi-page A4 PDF file
// (html2canvas + jsPDF), then opens a compose modal: recipient from the
// apartment config, a bilingual (EN/GR per apt.language) message with the key
// figures, an embedded page-1 preview, and the PDF attached. Sending goes
// through POST /api/email/send (nodemailer on the server, SMTP via Railway
// env vars). When SMTP isn't configured yet, the modal falls back to
// "download PDF + open mail app" so nothing is blocked.
// The sent record is stored inside the existing report lock entry
// (S.rptLocks[key].email) so it persists through every save/load path.

let _emailCfg = null;
async function _emailStatus(force) {
  if (_emailCfg && !force) return _emailCfg;
  try { const r = await fetch('/api/email/status'); _emailCfg = r.ok ? await r.json() : { configured: false }; }
  catch (e) { _emailCfg = { configured: false }; }
  return _emailCfg;
}

function _emailSlug(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'Report';
}

function _emailPdfName(d) {
  const per = d.dates.from.toISOString().slice(0, 10) + '_' + d.dates.to.toISOString().slice(0, 10);
  const who = d.packets.length > 1 ? d.packets.length + '-Properties' : _emailSlug(d.apt.name);
  return 'Elysian_Clearing_' + who + '_' + per + '.pdf';
}

// Pure pagination helper: choose page-break Y positions (CSS px) from a sorted
// list of "safe" element bottoms. Greedy: break at the largest safe bottom that
// still fits the page; hard-cut only when no safe bottom lands inside the page
// (guarding against degenerate tiny pages). Covered by self-tests Em1–Em4.
function _emailPageBreaks(bottoms, capacity, total) {
  const breaks = []; let y = 0;
  const EPS = 2;    // rendering fuzz
  const TAIL = 40;  // absorb a trailing sliver into the last page (bleeds ≤ ~10mm
                    // into the bottom margin instead of printing a near-empty page)
  while (total - y > capacity + TAIL) {
    let best = 0;
    for (const b of bottoms) { if (b > y + EPS && b <= y + capacity + EPS && b > best) best = b; }
    const next = best > y + capacity * 0.25 ? best : y + capacity;
    breaks.push(next); y = next;
  }
  return breaks;
}

async function _emailEnsureLibs() {
  const load = src => new Promise((res, rej) => {
    const s = document.createElement('script');
    s.src = src; s.onload = res; s.onerror = () => rej(new Error('Failed to load ' + src));
    document.head.appendChild(s);
  });
  if (typeof html2canvas === 'undefined') await load('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js');
  if (!(window.jspdf && window.jspdf.jsPDF)) await load('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
}

// Render the report HTML (same document as Export PDF) into a real A4 PDF.
// Returns { blob, base64, previewDataUrl, pages, fname, bytes }.
async function _emailRenderPdf(d) {
  await _emailEnsureLibs();
  const CSS_W = 688;                                   // 182mm content width @96dpi
  const CSS_PAGE_H = Math.floor(CSS_W * 267 / 182);    // 267mm content height → 1009px
  const frame = document.createElement('iframe');
  frame.style.cssText = 'position:fixed;left:-10000px;top:0;width:' + CSS_W + 'px;height:1200px;border:0;visibility:hidden';
  document.body.appendChild(frame);
  try {
    await new Promise(res => { frame.onload = res; frame.srcdoc = d.html; });
    const idoc = frame.contentDocument;
    idoc.body.style.width = CSS_W + 'px';
    await new Promise(res => setTimeout(res, 250));    // let the base64 logo + layout settle
    const total = idoc.body.scrollHeight;
    frame.style.height = (total + 40) + 'px';
    // Safe break candidates: bottoms of atomic blocks (sections, rows, table rows)
    const sel = '.hdr, .kpi-strip, .section, .frow, tr, .tax-card, .remit-box, .payout-box';
    const bottoms = [...new Set([...idoc.querySelectorAll(sel)].map(el => Math.round(el.getBoundingClientRect().bottom)))].sort((a, b) => a - b);
    const breaks = _emailPageBreaks(bottoms, CSS_PAGE_H, total);
    const canvas = await html2canvas(idoc.body, { scale: 2, backgroundColor: '#ffffff', windowWidth: CSS_W, width: CSS_W });
    const k = canvas.width / CSS_W;                    // device scale actually used
    const edges = [0, ...breaks, total];
    const pdf = new window.jspdf.jsPDF({ unit: 'mm', format: 'a4', compress: true });
    let previewDataUrl = '';
    for (let i = 0; i < edges.length - 1; i++) {
      const y0 = edges[i], y1 = Math.min(edges[i + 1], total), hCss = y1 - y0;
      if (hCss <= 1) continue;
      const pc = document.createElement('canvas');
      pc.width = canvas.width; pc.height = Math.round(hCss * k);
      const ctx = pc.getContext('2d');
      ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, pc.width, pc.height);
      ctx.drawImage(canvas, 0, Math.round(y0 * k), canvas.width, pc.height, 0, 0, pc.width, pc.height);
      const img = pc.toDataURL('image/jpeg', 0.87);
      if (i > 0) pdf.addPage();
      pdf.addImage(img, 'JPEG', 14, 15, 182, hCss * 182 / CSS_W);
      if (i === 0) {
        const tw = 720, th = Math.round(pc.height * tw / pc.width);
        const tc = document.createElement('canvas'); tc.width = tw; tc.height = th;
        tc.getContext('2d').drawImage(pc, 0, 0, tw, th);
        previewDataUrl = tc.toDataURL('image/jpeg', 0.8);
      }
    }
    const blob = pdf.output('blob');
    const buf = await blob.arrayBuffer();
    let bin = ''; const bytes = new Uint8Array(buf);
    for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    return { blob, base64: btoa(bin), previewDataUrl, pages: edges.length - 1, fname: _emailPdfName(d), bytes: buf.byteLength };
  } finally { frame.remove(); }
}

function _emailEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

