function _emailLogoB64(d) {
  const m = (d.html || '').match(/src="data:image\/jpeg;base64,([^"]+)"/);
  return m ? m[1] : '';
}

// One builder for both the modal preview (data-URL images) and the sent email
// (cid: images). Table-based inline styles for mail-client compatibility.
function _emailBuildHtml(st, introText, previewSrc, logoSrc) {
  const d = st.d, L = st.L, e = _emailEsc;
  const name = (d.apt.ownerName || '').trim() || L.fallbackName;
  const intro = e(introText).replace(/\n/g, '<br>');
  const row = (lbl, val, opts) => {
    const o = opts || {};
    return '<tr>'
      + '<td style="padding:6px 0;font-size:13px;color:' + (o.color || '#444') + ';' + (o.bold ? 'font-weight:700;' : '') + (o.top ? 'border-top:1px solid #ccc;padding-top:9px;' : 'border-bottom:1px solid #f0f0f0;') + '">' + lbl + '</td>'
      + '<td align="right" style="padding:6px 0;font-size:13px;font-family:\'Courier New\',monospace;color:' + (o.color || '#1a1a1a') + ';' + (o.bold ? 'font-weight:700;' : '') + (o.top ? 'border-top:1px solid #ccc;padding-top:9px;' : 'border-bottom:1px solid #f0f0f0;') + '">' + val + '</td>'
      + '</tr>';
  };
  let figs = '';
  figs += row(e(L.gross), fmt(d.m.gross));
  figs += row('&minus; ' + e(L.taxplat), '-' + fmt(d.dedSub), { color: '#c0392b' });
  figs += row('&minus; ' + e(L.ely) + (d.hasVat ? e(L.elyVat) : ''), '-' + fmt(d.elySub), { color: '#c0392b' });
  figs += row(e(L.net), fmt(d.netEarnings), { bold: true, top: true, color: '#0F1E2E' });
  figs += row('&minus; ' + e(L.mgmt(d.mgmtLbl)) + (d.mfVat > 0 ? e(L.mgmtVat) : ''), '-' + fmt(d.mf + d.mfVat), { color: '#c0392b' });
  if (d.b2bCount > 0) figs += row(e(L.b2b), fmt(d.b2bRem), { color: '#7C3AED', bold: true });
  const payLbl = d.b2bCount > 0 ? L.payTo : L.pay;
  return ''
    + '<div style="margin:0;padding:0;background:#f4f4f2">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f2"><tr><td align="center" style="padding:20px 8px">'
    + '<table role="presentation" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#ffffff;border-radius:8px;overflow:hidden;font-family:Helvetica,Arial,sans-serif;color:#1a1a1a">'
    // Header — mirrors the PDF: white, logo left, property + period right, navy rule
    + '<tr><td style="padding:18px 24px 12px 24px;border-bottom:3px solid #0F1E2E">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>'
    + '<td valign="middle">' + (logoSrc ? '<img src="' + logoSrc + '" height="46" alt="Elysian Properties" style="display:block;height:46px">' : '<span style="font-size:19px;font-weight:700;color:#0F1E2E">ELYSIAN</span>') + '</td>'
    + '<td valign="middle" align="right"><div style="font-size:15px;font-weight:700;color:#0F1E2E">' + e(d.propLbl) + '</div>'
    + '<div style="font-size:12px;color:#666;margin-top:2px">' + e(d.dates.lbl) + '</div></td>'
    + '</tr></table></td></tr>'
    // Body
    + '<tr><td style="padding:22px 24px 8px 24px">'
    + '<p style="margin:0 0 10px 0;font-size:14px">' + e(L.greet) + ' ' + e(name) + ',</p>'
    + '<p style="margin:0 0 16px 0;font-size:13.5px;line-height:1.55;color:#333">' + intro + '</p>'
    + '<div style="font-size:10px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:.07em;border-bottom:1px solid #e0e0e0;padding-bottom:5px;margin-bottom:2px">' + e(L.summary) + '</div>'
    + '<div style="font-size:11.5px;color:#777;padding:6px 0 2px 0">' + e(L.occ(d.bks.length, d.nights, d.totalDays, fmtPct(d.occ))) + '</div>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + figs + '</table>'
    + '</td></tr>'
    // Payout box
    + '<tr><td style="padding:10px 24px 4px 24px">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>'
    + '<td align="center" style="background:#0F1E2E;border-radius:6px;padding:14px 16px">'
    + '<div style="font-size:10px;color:#C9A84C;letter-spacing:.1em;text-transform:uppercase;margin-bottom:5px">' + e(payLbl) + '</div>'
    + '<div style="font-size:26px;font-weight:700;color:#C9A84C">' + fmt(d.payout) + '</div>'
    + '</td></tr></table></td></tr>'
    // Notes + preview
    + '<tr><td style="padding:14px 24px 6px 24px">'
    + (d.payout > 0 ? '<p style="margin:0 0 8px 0;font-size:13.5px;color:#333">' + e(L.transfer(fmt(d.payout))) + '</p>' : '')
    + '<p style="margin:0 0 14px 0;font-size:13.5px;color:#333">' + e(L.attach) + '</p>'
    + '<div style="font-size:11px;color:#888;margin-bottom:6px">' + e(L.previewCap(st.pdf.pages)) + '</div>'
