    + '</td></tr>'
    + '<tr><td style="background:#f9f9f7;padding:12px 24px;font-size:10px;color:#999">Elysian Property Management &middot; Clearing Report &middot; ' + e(d.propNames) + ' &middot; ' + e(new Date().toLocaleDateString('el-GR')) + '</td></tr>'
