function _emailBuildText(st, introText) {
  const d = st.d, L = st.L;
  const name = (d.apt.ownerName || '').trim() || L.fallbackName;
  const lines = [
    L.greet + ' ' + name + ',',
    '',
    introText,
    '',
    L.occ(d.bks.length, d.nights, d.totalDays, fmtPct(d.occ)),
    '',
    L.gross + ': ' + fmt(d.m.gross),
    '- ' + L.taxplat + ': ' + fmt(d.dedSub),
    '- ' + L.ely + (d.hasVat ? L.elyVat : '') + ': ' + fmt(d.elySub),
    L.net + ': ' + fmt(d.netEarnings),
    '- ' + L.mgmt(d.mgmtLbl) + (d.mfVat > 0 ? L.mgmtVat : '') + ': ' + fmt(d.mf + d.mfVat),
  ];
  if (d.b2bCount > 0) lines.push(L.b2b + ': ' + fmt(d.b2bRem));
  lines.push((d.b2bCount > 0 ? L.payTo : L.pay) + ': ' + fmt(d.payout));
  lines.push('');
  if (d.payout > 0) lines.push(L.transfer(fmt(d.payout)));
  lines.push(L.attach);
  lines.push('');
  lines.push(L.regards);
  lines.push('Elysian Properties');
  return lines.join('\n');
}

function _emailRecipients(d) {
  return [...new Set(d.packets.map(p => (p.a.ownerEmail || '').trim()).filter(Boolean))].join(', ');
}

function _emailPreviewRepaint() {
  const st = window._emailState; if (!st) return;
  const box = document.getElementById('em-preview'); if (!box) return;
  const intro = document.getElementById('em-intro')?.value || '';
  box.innerHTML = _emailBuildHtml(st, intro, st.pdf.previewDataUrl, st.logoSrc ? 'data:image/jpeg;base64,' + st.logoSrc : '');
}

function _emailModalClose() {
  const st = window._emailState;
  if (st && st.dlUrl) { try { URL.revokeObjectURL(st.dlUrl); } catch (e) {} }
  document.getElementById('email-modal')?.remove();
  window._emailState = null;
}

function _emailOpenMailApp() {
  const st = window._emailState; if (!st) return;
  const to = document.getElementById('em-to')?.value || '';
  const subj = document.getElementById('em-subj')?.value || '';
  const intro = document.getElementById('em-intro')?.value || '';
  window.location.href = 'mailto:' + encodeURIComponent(to) + '?subject=' + encodeURIComponent(subj) + '&body=' + encodeURIComponent(_emailBuildText(st, intro));
  toast('Opening email client — remember to attach the downloaded PDF.', 'warn');
}

async function _emailSend() {
  const st = window._emailState; if (!st) return;
  const to = (document.getElementById('em-to')?.value || '').trim();
  const cc = (document.getElementById('em-cc')?.value || '').trim();
  const subject = (document.getElementById('em-subj')?.value || '').trim();
  const intro = document.getElementById('em-intro')?.value || '';
  const status = document.getElementById('em-status');
  if (!to) { if (status) status.textContent = 'Add a recipient first (owner email is empty in Configuration).'; return; }
  const btn = document.getElementById('em-send');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
  if (status) status.textContent = '';
  try {
    const inline = [{ cid: 'p1', contentType: 'image/jpeg', contentBase64: (st.pdf.previewDataUrl.split(',')[1] || '') }];
    if (st.logoSrc) inline.push({ cid: 'elogo', contentType: 'image/jpeg', contentBase64: st.logoSrc });
    const html = _emailBuildHtml(st, intro, 'cid:p1', st.logoSrc ? 'cid:elogo' : '');
    const text = _emailBuildText(st, intro);
    const r = await fetch('/api/email/send', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to, cc, subject, html, text, inline,
        attachments: [{ filename: st.pdf.fname, contentType: 'application/pdf', contentBase64: st.pdf.base64 }],
      }),
    });
    const j = await r.json().catch(() => ({}));
    if (r.ok && j.ok) {
      _lockCurrentReport('email');
      const key = window._rptLockKey;
      if (key && S.rptLocks && S.rptLocks[key]) {
        S.rptLocks[key].email = { at: Date.now(), to, by: localStorage.getItem('elysian_user_name') || '' };
        save();
      }
      toast('Report emailed to ' + to, 'ok');
      const apt = st.d.apt;
      _emailModalClose();
      renderRpt();
      setTimeout(() => showPostReportReminders(apt), 500);
    } else {
      if (status) status.textContent = (j.error || ('Send failed (HTTP ' + r.status + ')'));
      if (btn) { btn.disabled = false; btn.textContent = '📨 Send email'; }
    }
  } catch (e) {
    if (status) status.textContent = 'Send failed: ' + e.message;
    if (btn) { btn.disabled = false; btn.textContent = '📨 Send email'; }
  }
}

function _emailModalOpen(d, pdf, cfg) {
  const isGR = (d.apt.language || 'EN') === 'GR';
  const L = _emailL(isGR);
  const logoSrc = _emailLogoB64(d);
  const dlUrl = URL.createObjectURL(pdf.blob);
  window._emailState = { d, pdf, cfg, isGR, L, logoSrc, dlUrl };
  const prev = S.rptLocks && S.rptLocks[window._rptLockKey] && S.rptLocks[window._rptLockKey].email;
  const introDefault = L.intro(L.propPhrase(d), d.dates.lbl);
  const sizeMB = (pdf.bytes / 1048576).toFixed(2);
  document.getElementById('email-modal')?.remove();
  const ov = document.createElement('div');
  ov.id = 'email-modal';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px';
  ov.addEventListener('click', ev => { if (ev.target === ov) _emailModalClose(); });
  ov.innerHTML = `
    <div style="background:var(--bg,#fff);border-radius:12px;max-width:900px;width:100%;max-height:92vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.35)" onclick="event.stopPropagation()">
      <div style="display:flex;align-items:center;gap:10px;padding:14px 18px;border-bottom:.5px solid var(--bdr2,#ddd)">
        <div style="font-weight:700;font-size:15px">📧 Email report to owner</div>
        <div style="flex:1"></div>
        <button class="btn" onclick="_emailModalClose()" style="padding:4px 10px">✕</button>
      </div>
      <div style="overflow:auto;padding:16px 18px;display:flex;flex-direction:column;gap:12px">
        ${prev ? `<div style="font-size:12px;color:#92400E;background:#FEF3C7;border:.5px solid #D97706;border-radius:6px;padding:8px 12px">Already emailed ${new Date(prev.at).toLocaleString('el-GR')} → ${_emailEsc(prev.to)}${prev.by ? ' (by ' + _emailEsc(prev.by) + ')' : ''}</div>` : ''}
        <div style="display:flex;gap:12px;flex-wrap:wrap">
          <div style="flex:2;min-width:240px">
            <div style="font-size:11px;color:var(--tx3,#888);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">To</div>
            <input type="text" id="em-to" value="${_emailEsc(_emailRecipients(d))}" placeholder="owner@email.com">
          </div>
          <div style="flex:1;min-width:180px">
            <div style="font-size:11px;color:var(--tx3,#888);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Cc (optional)</div>
            <input type="text" id="em-cc" value="" placeholder="">
          </div>
        </div>
        <div>
          <div style="font-size:11px;color:var(--tx3,#888);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Subject</div>
          <input type="text" id="em-subj" value="${_emailEsc(L.subj(d.propLbl, d.dates.lbl))}">
        </div>
        <div>
          <div style="font-size:11px;color:var(--tx3,#888);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Message to the owner <span style="text-transform:none;letter-spacing:0">(the figures, preview and attachment are added automatically)</span></div>
          <textarea id="em-intro" rows="3" oninput="clearTimeout(window._emIntroT);window._emIntroT=setTimeout(_emailPreviewRepaint,300)" style="width:100%;border:.5px solid var(--bdr2,#ccc);border-radius:8px;padding:7px 10px;font-size:13px;color:var(--tx,#1a1a1a);background:var(--bg,#fff);outline:none;resize:vertical;font-family:inherit">${_emailEsc(introDefault)}</textarea>
        </div>
        <div>
          <div style="font-size:11px;color:var(--tx3,#888);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Email preview</div>
          <div id="em-preview" style="border:.5px solid var(--bdr2,#ddd);border-radius:8px;overflow:auto;max-height:360px;background:#f4f4f2"></div>
        </div>
        <div style="display:flex;align-items:center;gap:10px;font-size:13px;flex-wrap:wrap">
          <span style="background:var(--bg2,#f5f5f0);border:.5px solid var(--bdr2,#ddd);border-radius:16px;padding:5px 12px">📎 ${_emailEsc(pdf.fname)} · ${sizeMB} MB · ${pdf.pages} page${pdf.pages === 1 ? '' : 's'}</span>
          <a href="${dlUrl}" download="${_emailEsc(pdf.fname)}" style="color:#C9A84C;text-decoration:underline;cursor:pointer">⬇ Download PDF</a>
        </div>
        ${cfg.configured ? '' : `<div style="font-size:12.5px;color:#92400E;background:#FEF3C7;border:.5px solid #D97706;border-radius:6px;padding:10px 12px">Email sending isn't configured on the server yet (SMTP_HOST / SMTP_USER / SMTP_PASS in Railway → Variables). Until then: download the PDF and use "Open mail app" — the message text is pre-filled, just attach the file.</div>`}
      </div>
      <div style="display:flex;align-items:center;gap:10px;padding:12px 18px;border-top:.5px solid var(--bdr2,#ddd)">
        <span id="em-status" style="flex:1;font-size:12.5px;color:#c0392b"></span>
        ${cfg.configured
          ? `<button class="btn" onclick="_emailModalClose()">Cancel</button>
             <button class="btn primary" id="em-send" onclick="_emailSend()">📨 Send email</button>`
          : `<button class="btn" onclick="_emailModalClose()">Close</button>
             <button class="btn" onclick="_emailOpenMailApp()">✉ Open mail app</button>
             <a class="btn primary" href="${dlUrl}" download="${_emailEsc(pdf.fname)}" style="text-decoration:none">⬇ Download PDF</a>`}
      </div>
    </div>`;
  document.body.appendChild(ov);
  _emailPreviewRepaint();
}

async function emailRpt() {
  const d = buildPdfDoc('email');
  if (!d) return;
  toast('Preparing the report PDF…');
  let pdf;
  try { pdf = await _emailRenderPdf(d); }
  catch (e) { console.error('[email] PDF render failed', e); toast('Could not render the PDF: ' + e.message, 'err'); return; }
  const cfg = await _emailStatus();
  _emailModalOpen(d, pdf, cfg);
}

// ── Em: email PDF pagination (pure helper) ──────────────────────────────────
if (typeof _emailPageBreaks === 'function') {
  assertEq('Em1 single page: no breaks', _emailPageBreaks([300, 600, 900], 1009, 900).length, 0);
  const em2 = _emailPageBreaks(Array.from({length:125},(_,i)=>(i+1)*20), 1009, 2500);
  assertEq('Em2 breaks land on row bottoms', em2.join(','), '1000,2000');
  const em3 = _emailPageBreaks([50, 3000], 1009, 3000);
  assertEq('Em3 hard-cut when no safe bottom in page', em3.join(','), '1009,2018');
  assertEq('Em4 trailing sliver absorbed into last page', _emailPageBreaks([1000, 2000], 1009, 2018).join(','), '1000');
  assertEq('Em5 fuzz tolerance: 1010 fits one page', _emailPageBreaks([500], 1009, 1010).length, 0);
} else {
  results.push({ name:'Em email pagination helper missing', pass:false, actual:'missing', expected:'function' });
}

